/** Category display name mapping */
export const categoryNames: Record<string, string> = {
  pdf: "PDF",
  image: "Image",
  calc: "Calc",
  dev: "Dev",
  security: "Security",
  file: "File",
  utils: "Utils",
  text: "Text",
  data: "Data",
  media: "Media",
  network: "Network",
};

/** All unique category ids */
export const categoryIds = [...new Set(tools.map(t => t.cat))];

/** Lookup a tool's SEO data by its href path. Returns undefined if not found. */
export function getToolByHref(href: string): ToolDefinition | undefined {
  return tools.find(t => {
    // Normalize: remove trailing slash
    const tHref = t.href.endsWith('/') && t.href.length > 1 ? t.href.slice(0, -1) : t.href;
    const input = href.endsWith('/') && href.length > 1 ? href.slice(0, -1) : href;
    return tHref === input;
  });
}

